import React, { useState, useEffect } from 'react';
import api from '../api';

function Templates() {
  const [templates, setTemplates] = useState([]);
  const [checklists, setChecklists] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showTemplateForm, setShowTemplateForm] = useState(false);
  const [showChecklistForm, setShowChecklistForm] = useState(false);
  const [showOneOffForm, setShowOneOffForm] = useState(false);

  const [templateFormData, setTemplateFormData] = useState({
    title: '',
    description: '',
    frequency: 'daily',
    checklist_id: ''
  });

  const [checklistFormData, setChecklistFormData] = useState({
    name: '',
    description: '',
    frequency: 'daily'
  });

  const [oneOffData, setOneOffData] = useState({
    title: '',
    description: '',
    frequency: 'daily',
    due_date: new Date().toISOString().split('T')[0],
    checklist_id: ''
  });

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [templatesData, checklistsData] = await Promise.all([
        api.getTemplates(),
        api.getChecklists()
      ]);
      setTemplates(templatesData);
      setChecklists(checklistsData);
    } catch (error) {
      console.error('Error loading data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateTemplate = async (e) => {
    e.preventDefault();
    try {
      await api.createTemplate({
        ...templateFormData,
        checklist_id: templateFormData.checklist_id || null
      });
      setTemplateFormData({ title: '', description: '', frequency: 'daily', checklist_id: '' });
      setShowTemplateForm(false);
      loadData();
    } catch (error) {
      console.error('Error creating template:', error);
    }
  };

  const handleCreateChecklist = async (e) => {
    e.preventDefault();
    try {
      await api.createChecklist(checklistFormData);
      setChecklistFormData({ name: '', description: '', frequency: 'daily' });
      setShowChecklistForm(false);
      loadData();
    } catch (error) {
      console.error('Error creating checklist:', error);
    }
  };

  const handleToggleTemplateActive = async (template) => {
    try {
      await api.updateTemplate(template.id, {
        ...template,
        is_active: template.is_active ? 0 : 1
      });
      loadData();
    } catch (error) {
      console.error('Error updating template:', error);
    }
  };

  const handleToggleChecklistActive = async (checklist) => {
    try {
      await api.updateChecklist(checklist.id, {
        ...checklist,
        is_active: checklist.is_active ? 0 : 1
      });
      loadData();
    } catch (error) {
      console.error('Error updating checklist:', error);
    }
  };

  const handleCreateOneOff = async (e) => {
    e.preventDefault();
    try {
      await api.createOneOffTask({
        ...oneOffData,
        checklist_id: oneOffData.checklist_id || null
      });
      setOneOffData({
        title: '',
        description: '',
        frequency: 'daily',
        due_date: new Date().toISOString().split('T')[0],
        checklist_id: ''
      });
      setShowOneOffForm(false);
      alert('One-off task created successfully!');
    } catch (error) {
      console.error('Error creating one-off task:', error);
    }
  };

  const getChecklistName = (checklistId) => {
    const checklist = checklists.find(c => c.id === checklistId);
    return checklist ? checklist.name : 'None';
  };

  if (loading) {
    return <div className="loading">Loading...</div>;
  }

  // Group templates by frequency
  const groupedTemplates = {
    daily: templates.filter(t => t.frequency === 'daily'),
    weekly: templates.filter(t => t.frequency === 'weekly'),
    monthly: templates.filter(t => t.frequency === 'monthly')
  };

  // Group checklists by frequency
  const groupedChecklists = {
    daily: checklists.filter(c => c.frequency === 'daily'),
    weekly: checklists.filter(c => c.frequency === 'weekly'),
    monthly: checklists.filter(c => c.frequency === 'monthly')
  };

  return (
    <div className="main-content">
      <div className="page-header">
        <h1>Manage Templates & Checklists</h1>
        <p>Create and manage recurring tasks and checklists</p>
      </div>

      <div style={{ display: 'flex', gap: '10px', marginBottom: '30px', flexWrap: 'wrap' }}>
        <button className="btn btn-primary" onClick={() => setShowChecklistForm(!showChecklistForm)}>
          {showChecklistForm ? 'Cancel' : '+ New Checklist'}
        </button>
        <button className="btn btn-primary" onClick={() => setShowTemplateForm(!showTemplateForm)}>
          {showTemplateForm ? 'Cancel' : '+ New Task Template'}
        </button>
        <button className="btn btn-success" onClick={() => setShowOneOffForm(!showOneOffForm)}>
          {showOneOffForm ? 'Cancel' : '+ One-Off Task'}
        </button>
      </div>

      {/* Create Checklist Form */}
      {showChecklistForm && (
        <div className="task-section" style={{ marginBottom: '30px' }}>
          <h3 style={{ marginBottom: '20px' }}>Create New Checklist</h3>
          <form onSubmit={handleCreateChecklist}>
            <div className="form-group">
              <label>Checklist Name</label>
              <input
                type="text"
                className="form-control"
                value={checklistFormData.name}
                onChange={(e) => setChecklistFormData({ ...checklistFormData, name: e.target.value })}
                required
                placeholder="e.g., AM Checklist, PM Checklist"
              />
            </div>
            <div className="form-group">
              <label>Description</label>
              <textarea
                className="form-control"
                value={checklistFormData.description}
                onChange={(e) => setChecklistFormData({ ...checklistFormData, description: e.target.value })}
                placeholder="Optional description"
              />
            </div>
            <div className="form-group">
              <label>Frequency</label>
              <select
                className="form-control"
                value={checklistFormData.frequency}
                onChange={(e) => setChecklistFormData({ ...checklistFormData, frequency: e.target.value })}
              >
                <option value="daily">Daily</option>
                <option value="weekly">Weekly</option>
                <option value="monthly">Monthly</option>
              </select>
            </div>
            <button type="submit" className="btn btn-primary">
              Create Checklist
            </button>
          </form>
        </div>
      )}

      {/* Create Task Template Form */}
      {showTemplateForm && (
        <div className="task-section" style={{ marginBottom: '30px' }}>
          <h3 style={{ marginBottom: '20px' }}>Create New Task Template</h3>
          <form onSubmit={handleCreateTemplate}>
            <div className="form-group">
              <label>Task Title</label>
              <input
                type="text"
                className="form-control"
                value={templateFormData.title}
                onChange={(e) => setTemplateFormData({ ...templateFormData, title: e.target.value })}
                required
                placeholder="e.g., Check emails"
              />
            </div>
            <div className="form-group">
              <label>Description</label>
              <textarea
                className="form-control"
                value={templateFormData.description}
                onChange={(e) => setTemplateFormData({ ...templateFormData, description: e.target.value })}
                placeholder="Optional description"
              />
            </div>
            <div className="form-group">
              <label>Frequency</label>
              <select
                className="form-control"
                value={templateFormData.frequency}
                onChange={(e) => setTemplateFormData({ ...templateFormData, frequency: e.target.value, checklist_id: '' })}
              >
                <option value="daily">Daily</option>
                <option value="weekly">Weekly</option>
                <option value="monthly">Monthly</option>
              </select>
            </div>
            <div className="form-group">
              <label>Assign to Checklist (Optional)</label>
              <select
                className="form-control"
                value={templateFormData.checklist_id}
                onChange={(e) => setTemplateFormData({ ...templateFormData, checklist_id: e.target.value })}
              >
                <option value="">None (Standalone Task)</option>
                {checklists
                  .filter(c => c.frequency === templateFormData.frequency)
                  .map(checklist => (
                    <option key={checklist.id} value={checklist.id}>
                      {checklist.name}
                    </option>
                  ))}
              </select>
            </div>
            <button type="submit" className="btn btn-primary">
              Create Task Template
            </button>
          </form>
        </div>
      )}

      {/* Create One-Off Task Form */}
      {showOneOffForm && (
        <div className="task-section" style={{ marginBottom: '30px' }}>
          <h3 style={{ marginBottom: '20px' }}>Create One-Off Task</h3>
          <form onSubmit={handleCreateOneOff}>
            <div className="form-group">
              <label>Task Title</label>
              <input
                type="text"
                className="form-control"
                value={oneOffData.title}
                onChange={(e) => setOneOffData({ ...oneOffData, title: e.target.value })}
                required
              />
            </div>
            <div className="form-group">
              <label>Description</label>
              <textarea
                className="form-control"
                value={oneOffData.description}
                onChange={(e) => setOneOffData({ ...oneOffData, description: e.target.value })}
              />
            </div>
            <div className="form-group">
              <label>Frequency Type</label>
              <select
                className="form-control"
                value={oneOffData.frequency}
                onChange={(e) => setOneOffData({ ...oneOffData, frequency: e.target.value, checklist_id: '' })}
              >
                <option value="daily">Daily</option>
                <option value="weekly">Weekly</option>
                <option value="monthly">Monthly</option>
              </select>
            </div>
            <div className="form-group">
              <label>Assign to Checklist (Optional)</label>
              <select
                className="form-control"
                value={oneOffData.checklist_id}
                onChange={(e) => setOneOffData({ ...oneOffData, checklist_id: e.target.value })}
              >
                <option value="">None (Standalone Task)</option>
                {checklists
                  .filter(c => c.frequency === oneOffData.frequency)
                  .map(checklist => (
                    <option key={checklist.id} value={checklist.id}>
                      {checklist.name}
                    </option>
                  ))}
              </select>
            </div>
            <div className="form-group">
              <label>Due Date</label>
              <input
                type="date"
                className="form-control"
                value={oneOffData.due_date}
                onChange={(e) => setOneOffData({ ...oneOffData, due_date: e.target.value })}
                required
              />
            </div>
            <button type="submit" className="btn btn-success">
              Create One-Off Task
            </button>
          </form>
        </div>
      )}

      {/* Checklists Section */}
      <div className="task-section" style={{ marginBottom: '30px' }}>
        <h2 style={{ marginBottom: '20px' }}>📋 Checklists</h2>

        {['daily', 'weekly', 'monthly'].map(freq => (
          groupedChecklists[freq].length > 0 && (
            <div key={freq} style={{ marginBottom: '30px' }}>
              <h3 style={{ marginBottom: '15px', textTransform: 'capitalize', color: '#7f8c8d' }}>
                {freq} Checklists
              </h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                {groupedChecklists[freq].map(checklist => (
                  <div
                    key={checklist.id}
                    style={{
                      border: '2px solid #3498db',
                      borderRadius: '6px',
                      padding: '15px',
                      backgroundColor: checklist.is_active ? 'white' : '#f5f5f5'
                    }}
                  >
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start' }}>
                      <div style={{ flex: 1 }}>
                        <h4 style={{ marginBottom: '5px', color: '#2c3e50' }}>{checklist.name}</h4>
                        {checklist.description && (
                          <p style={{ color: '#7f8c8d', fontSize: '14px', marginBottom: '10px' }}>
                            {checklist.description}
                          </p>
                        )}
                        <div style={{ display: 'flex', gap: '15px', fontSize: '14px' }}>
                          <span>
                            <strong>Frequency:</strong> {checklist.frequency}
                          </span>
                          <span>
                            <strong>Status:</strong>{' '}
                            <span style={{ color: checklist.is_active ? '#27ae60' : '#e74c3c' }}>
                              {checklist.is_active ? 'Active' : 'Inactive'}
                            </span>
                          </span>
                        </div>
                      </div>
                      <button
                        className={`btn ${checklist.is_active ? 'btn-secondary' : 'btn-success'}`}
                        onClick={() => handleToggleChecklistActive(checklist)}
                      >
                        {checklist.is_active ? 'Deactivate' : 'Activate'}
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )
        ))}
      </div>

      {/* Task Templates Section */}
      <div className="task-section">
        <h2 style={{ marginBottom: '20px' }}>📝 Task Templates</h2>

        {['daily', 'weekly', 'monthly'].map(freq => (
          groupedTemplates[freq].length > 0 && (
            <div key={freq} style={{ marginBottom: '30px' }}>
              <h3 style={{ marginBottom: '15px', textTransform: 'capitalize', color: '#7f8c8d' }}>
                {freq} Tasks
              </h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                {groupedTemplates[freq].map(template => (
                  <div
                    key={template.id}
                    style={{
                      border: '1px solid #e0e0e0',
                      borderRadius: '6px',
                      padding: '15px',
                      backgroundColor: template.is_active ? 'white' : '#f5f5f5'
                    }}
                  >
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start' }}>
                      <div style={{ flex: 1 }}>
                        <h4 style={{ marginBottom: '5px' }}>{template.title}</h4>
                        <p style={{ color: '#7f8c8d', fontSize: '14px', marginBottom: '10px' }}>
                          {template.description}
                        </p>
                        <div style={{ display: 'flex', gap: '15px', fontSize: '14px' }}>
                          <span>
                            <strong>Frequency:</strong> {template.frequency}
                          </span>
                          <span>
                            <strong>Checklist:</strong> {getChecklistName(template.checklist_id)}
                          </span>
                          <span>
                            <strong>Status:</strong>{' '}
                            <span style={{ color: template.is_active ? '#27ae60' : '#e74c3c' }}>
                              {template.is_active ? 'Active' : 'Inactive'}
                            </span>
                          </span>
                        </div>
                      </div>
                      <button
                        className={`btn ${template.is_active ? 'btn-secondary' : 'btn-success'}`}
                        onClick={() => handleToggleTemplateActive(template)}
                      >
                        {template.is_active ? 'Deactivate' : 'Activate'}
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )
        ))}
      </div>
    </div>
  );
}

export default Templates;
